"Объём кузова: 4 · 2 · 1 = 8 м³. 40 : 8 = 5 (рейсов).": "Ҳаҷми кузов: 4 · 2 · 1 = 8 м³. 40 : 8 = 5 (рейс).",
"Треугольник с прямым углом называется прямоугольным.": "Секунҷа бо кунҷи рост росткунҷа номида мешавад.",
"площадь 48 см²: прямоугольник 6 × 8 (в сумме 48 см²)": "масоҳат 48 см²: росткунҷаи 6 × 8 (дар маҷмӯъ 48 см²)",
