"Найди все натуральные решения неравенства 5 < x < 11.": "Ҳамаи ҳалҳои натуралии нобаробарии 5 < x < 11-ро ёб.",
"Объём коробки 64 см³, объём кубика 8 см³, 64 : 8 = 8.": "Ҳаҷми қуттӣ 64 см³, ҳаҷми кубик 8 см³, 64 : 8 = 8.",
"180 − 90 − 35 = 55°. Сумма углов треугольника — 180°.": "180 − 90 − 35 = 55°. Ҷамъи кунҷҳои секунҷа — 180°.",
