"Перпендикулярные прямые пересекаются под прямым углом.": "Хатҳои перпендикуляр зери кунҷи рост бурида мешаванд.",
"Осей 4: две через середины сторон и две по диагоналям.": "Меҳварҳо 4 то: ду аз миёнаи тарафҳо ва ду аз рӯи диагоналҳо.",
"Урок 5. Числовые и буквенные выражения. Преобразование": "Дарси 5. Ифодаҳои ададӣ ва ҳарфӣ. Табдилдиҳӣ",
"Сколько натуральных решений у неравенства 99 < x < 106?": "Нобаробарии 99 < x < 106 чанд ҳалли натуралӣ дорад?",
"Проверка: подставим 60 — слева получится 4, как справа.": "Санҷиш: 60-ро ҷойгузин мекунем — дар чап 4 мешавад, мисли дар рост.",
