"предмет, развёртка которого — прямоугольник и два круга": "ашёе, ки тарҳи кушодаи он — росткунҷа ва ду доира аст",
"Меньшее число пишем слева, большее справа: 60 < n < 150.": "Адади хурдтарро дар чап менависем, калонтарро дар рост: 60 < n < 150.",
"Лишнее данное в задаче не нужно для ответа на её вопрос.": "Маълумоти зиёдатии масъала барои ҷавоб ба саволи он лозим нест.",
"объём больше 500 см³: рёбра 10, 10, 10 см (V = 1000 см³)": "ҳаҷм аз 500 см³ калон: қабурғаҳо 10, 10, 10 см (V = 1000 см³)",
"остроугольный: углы 50°, 60° и 70° (все углы меньше 90°)": "тезкунҷа: кунҷҳо 50°, 60° ва 70° (ҳамаи кунҷҳо аз 90° хурданд)",
