"Числа между 24 и 30: 25, 26, 27, 28, 29. Наибольшее — 29.": "Ададҳои байни 24 ва 30: 25, 26, 27, 28, 29. Калонтарин — 29.",
"тупоугольный: углы 110°, 40° и 30° (есть угол больше 90°)": "кундкунҷа: кунҷҳо 110°, 40° ва 30° (кунҷи аз 90° калон ҳаст)",
"Углы треугольника: 90°, 25° и 65°. Какой это треугольник?": "Кунҷҳои секунҷа: 90°, 25° ва 65°. Ин кадом секунҷа аст?",
"Числа 6 и 14 симметричны относительно оси через число 10.": "Ададҳои 6 ва 14 нисбат ба меҳвари аз адади 10 гузаранда симметрӣ мебошанд.",
"5 = 10 : 2. Поэтому 48 · 5 = 48 · 10 : 2 = 480 : 2 = 240.": "5 = 10 : 2. Барои ҳамин 48 · 5 = 48 · 10 : 2 = 480 : 2 = 240.",
"В решения не входит граница 17. Верно: { 13, 14, 15, 16 }.": "Ҳудуди 17 ба ҳалҳо дохил намешавад. Дуруст: { 13, 14, 15, 16 }.",
"Выражение a − 3 · b значит: из a вычли произведение 3 и b.": "Ифодаи a − 3 · b маънои онро дорад: аз a ҳосили зарби 3 ва b-ро тарҳ карданд.",
"Стороны треугольника: 13, 13 и 13 дм. Чему равен периметр?": "Тарафҳои секунҷа: 13, 13 ва 13 дм. Периметр ба чанд баробар аст?",
"Если два угла треугольника 90° и 40°, то третий равен 50°.": "Агар ду кунҷи секунҷа 90° ва 40° бошад, пас сеюмӣ ба 50° баробар аст.",
